/*
 * A220698  Indices of triangular numbers generated in A224218.
 * https://oeis.org/A220698
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = i where A000217(i) = A220689(n) Sequence of indices of
 *            triangular numbers generated by XOR of consecutive triangles
 * Range:     u8 n <= 1, u16 n <= 5, u32 n <= 63, u64 n <= 63, u128 n <= 63,
 *            big any n
 * Validated: partial, pass, 63 terms through n = 63 (2026-11-01)
 * Helpers:   ipow_i32
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include "../utils/ipow_i32.h"

/* Floor square root by binary search */
static inline seq_t floor_sqrt(seq_t x)
{
    seq_t lo = 0, hi = 1;
    while (ipow_i32(hi, 2) <= x)
        hi <<= 1;
    while (lo < hi)
    {
        seq_t mid = (lo + hi) >> 1;
        seq_t mid2 = mid * mid;
        if (mid2 <= x)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo - 1;
}

seq_t a(idx_t n)
{
    /* Handle invalid n gracefully */
    if (n == 0)
        return 0;

    idx_t i;
    idx_t seen = 0;
    seq_t result = 0;

    for (i = 0;; ++i)
    {
        /* t_i = i*(i+1)/2 and t_{i+1} */
        seq_t t_i   = (seq_t)i * ((seq_t)i + 1) / 2;
        seq_t t_ip1 = (seq_t)(i + 1) * ((seq_t)(i + 1) + 1) / 2;

        /* S = t_i XOR t_{i+1} */
        seq_t S = t_i ^ t_ip1;

        /* Check if S is a triangular number:
           S = k*(k+1)/2  <=>  8*S + 1 is a perfect square */
        seq_t D = S * 8 + 1;
        seq_t sD = floor_sqrt(D);

        if (sD * sD == D)
        {
            /* Compute k = (sD - 1)/2 */
            seq_t k = (sD - 1) / 2;
            seen++;
            if (seen == n)
            {
                result = k;
                break;
            }
        }
    }

    return result;
}
